/**
 * localCache.ts
 * Client-side helpers for the ThreatLens Feed Cache API (localhost:3001).
 *
 * The API is a local Docker service (Redis Stack + Express) that stores
 * threat feed items and supports full-text search.
 *
 * All functions fail silently — if the cache is offline the app continues
 * to work via Supabase.
 */

export const CACHE_API = "/api/feeds";

// ── Types ─────────────────────────────────────────────────────────────────────
export interface CacheFeedItem {
  id: string;
  title: string;
  excerpt?: string;
  link?: string;
  severity: string;
  source_name: string;
  category: string;
  published_at: string;
  cached_at?: string;
  ai_summary?: string;
  [key: string]: unknown;
}

export interface CacheStatus {
  online: boolean;
  feed_count: number;
  index: "ready" | "unavailable" | string;
}

// ── Status ────────────────────────────────────────────────────────────────────
export async function checkCacheStatus(): Promise<CacheStatus> {
  try {
    const r = await fetch(`${CACHE_API}/health`, { signal: AbortSignal.timeout(3000) });
    if (!r.ok) return { online: false, feed_count: 0, index: "unavailable" };
    const d = await r.json();
    return { online: true, feed_count: Number(d.feed_count ?? 0), index: d.index ?? "unknown" };
  } catch {
    return { online: false, feed_count: 0, index: "unavailable" };
  }
}

// ── Push ──────────────────────────────────────────────────────────────────────
export async function pushFeed(item: Partial<CacheFeedItem>): Promise<boolean> {
  try {
    const r = await fetch(`${CACHE_API}/api/feeds`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(item),
      signal: AbortSignal.timeout(5000),
    });
    return r.ok;
  } catch {
    return false;
  }
}

export async function pushFeedsBulk(items: Partial<CacheFeedItem>[]): Promise<number> {
  if (!items.length) return 0;
  let stored = 0;
  for (let i = 0; i < items.length; i += 100) {
    const batch = items.slice(i, i + 100);
    try {
      const r = await fetch(`${CACHE_API}/api/feeds/bulk`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(batch),
        signal: AbortSignal.timeout(15000),
      });
      if (r.ok) {
        const d = await r.json();
        stored += Number(d.stored ?? 0);
      }
    } catch { /* silent */ }
  }
  return stored;
}

// ── Search ────────────────────────────────────────────────────────────────────
export interface CacheSearchOptions {
  source_name?: string;
  severity?: string;
  category?: string;
  limit?: number;
}

export async function searchCache(
  query: string,
  opts: CacheSearchOptions = {}
): Promise<{ results: CacheFeedItem[]; total: number; fromCache: boolean }> {
  try {
    const params = new URLSearchParams();
    const q = query.trim();
    if (q) params.set("q", q);
    if (opts.source_name) params.set("source_name", opts.source_name);
    if (opts.severity)    params.set("severity", opts.severity);
    if (opts.category)    params.set("category", opts.category);
    params.set("limit", String(opts.limit ?? 50));

    const r = await fetch(`${CACHE_API}/api/feeds/search?${params}`, {
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return { results: [], total: 0, fromCache: false };
    const d = await r.json();
    return {
      results: (d.results ?? []) as CacheFeedItem[],
      total: Number(d.total ?? 0),
      fromCache: true,
    };
  } catch {
    return { results: [], total: 0, fromCache: false };
  }
}

// ── Retrieve ──────────────────────────────────────────────────────────────────
export async function getRecentFromCache(
  limit = 100,
  filters: CacheSearchOptions = {}
): Promise<CacheFeedItem[]> {
  try {
    const params = new URLSearchParams({ limit: String(limit) });
    if (filters.source_name) params.set("source_name", filters.source_name);
    if (filters.severity)    params.set("severity", filters.severity);
    if (filters.category)    params.set("category", filters.category);

    const r = await fetch(`${CACHE_API}/api/feeds?${params}`, {
      signal: AbortSignal.timeout(6000),
    });
    if (!r.ok) return [];
    const d = await r.json();
    return (d.items ?? []) as CacheFeedItem[];
  } catch {
    return [];
  }
}

// ── Clear ─────────────────────────────────────────────────────────────────────
export async function clearCache(): Promise<number> {
  try {
    const r = await fetch(`${CACHE_API}/api/feeds`, {
      method: "DELETE",
      signal: AbortSignal.timeout(8000),
    });
    if (!r.ok) return 0;
    const d = await r.json();
    return Number(d.cleared ?? 0);
  } catch {
    return 0;
  }
}
